const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "app", .root_module = mod });
    b.installArtifact(exe);

    const run = b.addRunArtifact(exe);
    run.step.dependOn(b.getInstallStep());
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run the server").dependOn(&run.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Thread-safe in-memory key/value store.
//!
//! Keys and values are owned by the store. Readers receive copies so the lock
//! is never held while a response is being written to a (possibly slow) peer.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

const Store = @This();

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(store: *Store) void {
    var it = store.map.iterator();
    while (it.next()) |entry| {
        store.gpa.free(entry.key_ptr.*);
        store.gpa.free(entry.value_ptr.*);
    }
    store.map.deinit(store.gpa);
    store.* = undefined;
}

pub const PutResult = enum { created, replaced };

/// Stores a copy of `value` under `key`.
pub fn put(store: *Store, io: Io, key: []const u8, value: []const u8) Allocator.Error!PutResult {
    const owned_value = try store.gpa.dupe(u8, value);
    errdefer store.gpa.free(owned_value);

    store.lock.lockUncancelable(io);
    defer store.lock.unlock(io);

    const gop = try store.map.getOrPut(store.gpa, key);
    if (gop.found_existing) {
        store.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = owned_value;
        return .replaced;
    }
    gop.key_ptr.* = store.gpa.dupe(u8, key) catch |err| {
        store.map.removeByPtr(gop.key_ptr);
        return err;
    };
    gop.value_ptr.* = owned_value;
    return .created;
}

/// Returns a copy of the value stored under `key`, allocated with `allocator`.
pub fn get(store: *Store, io: Io, allocator: Allocator, key: []const u8) Allocator.Error!?[]u8 {
    store.lock.lockSharedUncancelable(io);
    defer store.lock.unlockShared(io);

    const value = store.map.get(key) orelse return null;
    return try allocator.dupe(u8, value);
}

/// Removes `key`; returns whether it was present.
pub fn remove(store: *Store, io: Io, key: []const u8) bool {
    store.lock.lockUncancelable(io);
    defer store.lock.unlock(io);

    const entry = store.map.fetchRemove(key) orelse return false;
    store.gpa.free(entry.key);
    store.gpa.free(entry.value);
    return true;
}

/// Returns copies of every key in ascending byte order, allocated with `allocator`.
pub fn keys(store: *Store, io: Io, allocator: Allocator) Allocator.Error![]const []const u8 {
    store.lock.lockSharedUncancelable(io);
    defer store.lock.unlockShared(io);

    const out = try allocator.alloc([]const u8, store.map.count());
    var it = store.map.keyIterator();
    var i: usize = 0;
    while (it.next()) |key| : (i += 1) {
        out[i] = try allocator.dupe(u8, key.*);
    }
    std.mem.sortUnstable([]const u8, out, {}, lessThan);
    return out;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

test "put, get, remove and sorted keys" {
    const io = std.testing.io;
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();

    var store: Store = .init(std.testing.allocator);
    defer store.deinit();

    try std.testing.expectEqual(PutResult.created, try store.put(io, "b", "2"));
    try std.testing.expectEqual(PutResult.created, try store.put(io, "a", "1"));
    try std.testing.expectEqual(PutResult.replaced, try store.put(io, "b", "two"));
    try std.testing.expectEqualStrings("two", (try store.get(io, arena.allocator(), "b")).?);

    const listed = try store.keys(io, arena.allocator());
    try std.testing.expectEqual(2, listed.len);
    try std.testing.expectEqualStrings("a", listed[0]);
    try std.testing.expectEqualStrings("b", listed[1]);

    try std.testing.expect(store.remove(io, "a"));
    try std.testing.expect(!store.remove(io, "a"));
    try std.testing.expectEqual(null, try store.get(io, arena.allocator(), "a"));
}

//! Minimal HTTP/1.1 request parser and response serialiser.
//!
//! One request is served per connection, so there is no keep-alive or
//! pipelining support: every response carries `Connection: close`.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

pub const Status = std.http.Status;

pub const max_header_bytes = 64 * 1024;
pub const max_body_bytes = 1024 * 1024;

/// Size of the read buffer a connection must provide; it bounds the length of
/// a single request or header line.
pub const read_buffer_len = max_header_bytes + 1024;

pub const Header = struct {
    name: []const u8,
    value: []const u8,
};

pub const Request = struct {
    method: []const u8,
    target: []const u8,
    headers: []const Header,
    body: []const u8,

    /// Case-insensitive header lookup; returns the first match.
    pub fn header(req: *const Request, name: []const u8) ?[]const u8 {
        for (req.headers) |h| {
            if (std.ascii.eqlIgnoreCase(h.name, name)) return h.value;
        }
        return null;
    }
};

pub const Response = struct {
    status: Status = .ok,
    content_type: ?[]const u8 = null,
    body: []const u8 = "",

    pub fn empty(status: Status) Response {
        return .{ .status = status };
    }
};

/// Reasons a request could not be read. Each maps to a response status via
/// `errorStatus`.
pub const ReadError = error{
    BadRequest,
    HeaderFieldsTooLarge,
    ContentTooLarge,
    NotImplemented,
    /// The underlying reader failed (timeout, reset, ...).
    ReadFailed,
    OutOfMemory,
};

pub fn errorStatus(err: ReadError) Status {
    return switch (err) {
        error.BadRequest => .bad_request,
        error.HeaderFieldsTooLarge => .request_header_fields_too_large,
        error.ContentTooLarge => .payload_too_large,
        error.NotImplemented => .not_implemented,
        error.ReadFailed => .request_timeout,
        error.OutOfMemory => .internal_server_error,
    };
}

/// Reads one request. Returns null if the peer closed the connection before
/// sending anything. All returned memory is allocated with `arena`.
pub fn readRequest(arena: Allocator, r: *Io.Reader) ReadError!?Request {
    r.fill(1) catch |err| switch (err) {
        error.EndOfStream => return null,
        error.ReadFailed => return error.ReadFailed,
    };

    // Tolerate stray blank lines before the request line (RFC 9112 §2.2).
    var request_line = try readLine(r);
    while (request_line.len == 0) request_line = try readLine(r);
    var header_bytes: usize = request_line.len;

    const sp1 = std.mem.indexOfScalar(u8, request_line, ' ') orelse return error.BadRequest;
    const sp2 = std.mem.indexOfScalarPos(u8, request_line, sp1 + 1, ' ') orelse return error.BadRequest;
    if (sp1 == 0 or sp2 == sp1 + 1) return error.BadRequest;
    if (!std.mem.startsWith(u8, request_line[sp2 + 1 ..], "HTTP/")) return error.BadRequest;
    const method = try arena.dupe(u8, request_line[0..sp1]);
    const target = try arena.dupe(u8, request_line[sp1 + 1 .. sp2]);

    var headers: std.ArrayList(Header) = .empty;
    while (true) {
        const line = try readLine(r);
        if (line.len == 0) break;
        header_bytes += line.len;
        if (header_bytes > max_header_bytes) return error.HeaderFieldsTooLarge;
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
        if (colon == 0) return error.BadRequest;
        try headers.append(arena, .{
            .name = try arena.dupe(u8, line[0..colon]),
            .value = try arena.dupe(u8, trim(line[colon + 1 ..])),
        });
    }

    var req: Request = .{
        .method = method,
        .target = target,
        .headers = headers.items,
        .body = "",
    };

    if (req.header("Transfer-Encoding")) |te| {
        if (!std.ascii.eqlIgnoreCase(te, "chunked")) return error.NotImplemented;
        req.body = try readChunkedBody(arena, r);
    } else if (req.header("Content-Length")) |cl| {
        const len = try parseSize(cl, 10);
        if (len > max_body_bytes) return error.ContentTooLarge;
        req.body = r.readAlloc(arena, len) catch |err| switch (err) {
            error.EndOfStream => return error.BadRequest,
            error.ReadFailed => return error.ReadFailed,
            error.OutOfMemory => return error.OutOfMemory,
        };
    }
    return req;
}

fn readChunkedBody(arena: Allocator, r: *Io.Reader) ReadError![]const u8 {
    var body: std.ArrayList(u8) = .empty;
    while (true) {
        const line = try readLine(r);
        const size_part = if (std.mem.indexOfScalar(u8, line, ';')) |semi| line[0..semi] else line;
        const size = try parseSize(trim(size_part), 16);
        if (size == 0) break;
        if (size > max_body_bytes - body.items.len) return error.ContentTooLarge;
        const dest = try body.addManyAsSlice(arena, size);
        r.readSliceAll(dest) catch |err| switch (err) {
            error.EndOfStream => return error.BadRequest,
            error.ReadFailed => return error.ReadFailed,
        };
        if ((try readLine(r)).len != 0) return error.BadRequest;
    }
    // Trailer section, terminated by an empty line.
    var trailer_bytes: usize = 0;
    while (true) {
        const line = try readLine(r);
        if (line.len == 0) break;
        trailer_bytes += line.len;
        if (trailer_bytes > max_header_bytes) return error.HeaderFieldsTooLarge;
    }
    return body.items;
}

/// Returns the next line without its CRLF (or bare LF) terminator. The slice
/// points into the reader's buffer and is invalidated by the next read.
fn readLine(r: *Io.Reader) ReadError![]const u8 {
    const line = r.takeDelimiterInclusive('\n') catch |err| switch (err) {
        error.StreamTooLong => return error.HeaderFieldsTooLarge,
        error.EndOfStream => return error.BadRequest,
        error.ReadFailed => return error.ReadFailed,
    };
    const without_lf = line[0 .. line.len - 1];
    return std.mem.trimEnd(u8, without_lf, "\r");
}

fn trim(s: []const u8) []const u8 {
    return std.mem.trim(u8, s, " \t");
}

/// Strict unsigned parse: digits only, no sign, no separators, no overflow.
fn parseSize(s: []const u8, base: u8) error{BadRequest}!usize {
    if (s.len == 0) return error.BadRequest;
    var value: usize = 0;
    for (s) |c| {
        const digit = std.fmt.charToDigit(c, base) catch return error.BadRequest;
        value = std.math.mul(usize, value, base) catch return error.BadRequest;
        value = std.math.add(usize, value, digit) catch return error.BadRequest;
    }
    return value;
}

/// Serialises `res`, always with `Connection: close`, and flushes `w`.
pub fn writeResponse(w: *Io.Writer, res: Response) Io.Writer.Error!void {
    try w.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(res.status), res.status.phrase() orelse "Unknown" });
    if (res.content_type) |content_type| {
        try w.print("Content-Type: {s}\r\n", .{content_type});
    }
    // 204 must not carry a body or Content-Length framing; everything else
    // advertises its exact length.
    if (res.status != .no_content) {
        try w.print("Content-Length: {d}\r\n", .{res.body.len});
    }
    try w.writeAll("Connection: close\r\n\r\n");
    try w.writeAll(res.body);
    try w.flush();
}

fn testParse(arena: Allocator, raw: []const u8) ReadError!?Request {
    const buf = try arena.alloc(u8, read_buffer_len);
    var stream: Io.Reader = .fixed(raw);
    // Route through a buffered reader so line limits behave as on a socket.
    var limited = stream.limited(.unlimited, buf);
    return readRequest(arena, &limited.interface);
}

test "parses request line, headers and body" {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    const req = (try testParse(arena.allocator(), "\r\nPUT /kv/a HTTP/1.1\r\ncontent-length: 5\r\nHost:  x \r\n\r\nhello")).?;
    try std.testing.expectEqualStrings("PUT", req.method);
    try std.testing.expectEqualStrings("/kv/a", req.target);
    try std.testing.expectEqualStrings("x", req.header("host").?);
    try std.testing.expectEqualStrings("hello", req.body);
}

test "parses chunked body" {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    const raw = "POST / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n5;ext=1\r\nhello\r\n6\r\n world\r\n0\r\nX: y\r\n\r\n";
    const req = (try testParse(arena.allocator(), raw)).?;
    try std.testing.expectEqualStrings("hello world", req.body);
}

test "rejects malformed requests" {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try std.testing.expectEqual(null, try testParse(a, ""));
    try std.testing.expectError(error.BadRequest, testParse(a, "GET /\r\n\r\n"));
    try std.testing.expectError(error.BadRequest, testParse(a, "GET  / HTTP/1.1\r\n\r\n"));
    try std.testing.expectError(error.BadRequest, testParse(a, "GET / FTP/1.1\r\n\r\n"));
    try std.testing.expectError(error.BadRequest, testParse(a, "GET / HTTP/1.1\r\nnocolon\r\n\r\n"));
    try std.testing.expectError(error.BadRequest, testParse(a, "PUT / HTTP/1.1\r\nContent-Length: +5\r\n\r\nhello"));
    try std.testing.expectError(error.BadRequest, testParse(a, "PUT / HTTP/1.1\r\nContent-Length: 9\r\n\r\nhello"));
    try std.testing.expectError(error.ContentTooLarge, testParse(a, "PUT / HTTP/1.1\r\nContent-Length: 1048577\r\n\r\n"));
    try std.testing.expectError(error.NotImplemented, testParse(a, "PUT / HTTP/1.1\r\nTransfer-Encoding: gzip\r\n\r\n"));
}

test "serialises responses" {
    var buf: [256]u8 = undefined;
    var w: Io.Writer = .fixed(&buf);
    try writeResponse(&w, .{ .status = .ok, .content_type = "text/plain", .body = "ok" });
    try std.testing.expectEqualStrings(
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok",
        w.buffered(),
    );

    w = .fixed(&buf);
    try writeResponse(&w, .empty(.no_content));
    try std.testing.expectEqualStrings("HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n", w.buffered());
}

//! kvhttp: an HTTP/1.1 in-memory key/value server.
//!
//! Usage: `app <port>` — listens on 127.0.0.1:<port> until killed.

const std = @import("std");
const Io = std.Io;
const net = Io.net;
const Allocator = std.mem.Allocator;

const http = @import("http.zig");
const router = @import("router.zig");
const Store = @import("Store.zig");

const log = std.log.scoped(.kvhttp);

/// How long a peer may stay silent while we are reading its request.
const read_timeout: Io.Duration = .fromSeconds(30);
/// How long to wait for the peer to finish sending after we replied.
const drain_timeout: Io.Duration = .fromSeconds(2);
/// Upper bound on unread request bytes discarded after replying.
const max_drain_bytes = 64 * 1024 * 1024;

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    if (args.len != 2) {
        log.err("usage: {s} <port>", .{if (args.len > 0) args[0] else "app"});
        std.process.exit(2);
    }
    const port = parsePort(args[1]) orelse {
        log.err("invalid port '{s}'", .{args[1]});
        std.process.exit(2);
    };

    std.process.raiseFileDescriptorLimit();

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var server = address.listen(io, .{ .reuse_address = true, .kernel_backlog = 1024 }) catch |err|
        std.process.fatal("listen on 127.0.0.1:{d}: {t}", .{ port, err });
    defer server.deinit(io);

    var store: Store = .init(gpa);
    defer store.deinit();

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = server.accept(io) catch |err| switch (err) {
            error.ConnectionAborted => continue,
            error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded, error.SystemResources => {
                // Back off until in-flight connections release descriptors.
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => |e| return e,
        };
        connections.concurrent(io, serveConnection, .{ io, gpa, &store, stream }) catch |err| {
            log.warn("dropping connection: {t}", .{err});
            stream.close(io);
        };
    }
}

fn parsePort(arg: []const u8) ?u16 {
    if (arg.len == 0) return null;
    for (arg) |c| if (!std.ascii.isDigit(c)) return null;
    const port = std.fmt.parseInt(u16, arg, 10) catch return null;
    return if (port == 0) null else port;
}

fn serveConnection(io: Io, gpa: Allocator, store: *Store, stream: net.Stream) void {
    defer stream.close(io);

    var arena_state: std.heap.ArenaAllocator = .init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const read_buffer = arena.alloc(u8, http.read_buffer_len) catch return;
    var reader: TimedReader = .init(io, stream, read_buffer, read_timeout);

    const response: http.Response = response: {
        const request = http.readRequest(arena, &reader.interface) catch |err| {
            break :response .empty(http.errorStatus(err));
        } orelse return;
        break :response router.handle(io, arena, store, &request) catch |err| {
            log.err("request failed: {t}", .{err});
            break :response .empty(.internal_server_error);
        };
    };

    var write_buffer: [4096]u8 = undefined;
    var writer = stream.writer(io, &write_buffer);
    http.writeResponse(&writer.interface, response) catch return;

    // Send FIN, then discard any unread request bytes (e.g. an oversized body
    // we rejected) so closing does not trigger a RST that could clobber the
    // reply.
    stream.shutdown(io, .send) catch return;
    reader.timeout = drain_timeout;
    var drained: usize = 0;
    while (drained < max_drain_bytes) {
        drained += reader.interface.discard(.limited(max_drain_bytes - drained)) catch break;
    }
}

/// `Io.Reader` over a TCP stream that fails with `error.ReadFailed` (and sets
/// `err` to `error.Timeout`) when the peer stays silent for longer than
/// `timeout`.
const TimedReader = struct {
    io: Io,
    socket: net.Socket,
    timeout: Io.Duration,
    interface: Io.Reader,
    err: ?net.Socket.ReceiveTimeoutError = null,

    fn init(io: Io, stream: net.Stream, buffer: []u8, timeout: Io.Duration) TimedReader {
        return .{
            .io = io,
            .socket = stream.socket,
            .timeout = timeout,
            .interface = .{
                .vtable = &.{ .stream = streamImpl },
                .buffer = buffer,
                .seek = 0,
                .end = 0,
            },
        };
    }

    fn streamImpl(r: *Io.Reader, w: *Io.Writer, limit: Io.Limit) Io.Reader.StreamError!usize {
        const self: *TimedReader = @alignCast(@fieldParentPtr("interface", r));
        const dest = limit.slice(try w.writableSliceGreedy(1));
        const message = self.socket.receiveTimeout(self.io, dest, .{
            .duration = .{ .raw = self.timeout, .clock = .awake },
        }) catch |err| {
            self.err = err;
            return error.ReadFailed;
        };
        if (message.data.len == 0) return error.EndOfStream;
        w.advance(message.data.len);
        return message.data.len;
    }
};

test parsePort {
    try std.testing.expectEqual(8080, parsePort("8080"));
    try std.testing.expectEqual(65535, parsePort("65535"));
    try std.testing.expectEqual(null, parsePort("0"));
    try std.testing.expectEqual(null, parsePort("65536"));
    try std.testing.expectEqual(null, parsePort("+80"));
    try std.testing.expectEqual(null, parsePort(""));
}

test {
    _ = http;
    _ = router;
    _ = Store;
}

//! Maps requests onto the key/value API.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

const http = @import("http.zig");
const Store = @import("Store.zig");

const kv_prefix = "/kv/";
const max_key_len = 64;

/// True if `key` matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| {
        if (!std.ascii.isAlphanumeric(c) and c != '_' and c != '-') return false;
    }
    return true;
}

/// Handles `req`. Response bodies are allocated with `arena`.
pub fn handle(io: Io, arena: Allocator, store: *Store, req: *const http.Request) Allocator.Error!http.Response {
    const path = req.target;
    const method = req.method;

    if (std.mem.eql(u8, path, "/health")) {
        if (!std.mem.eql(u8, method, "GET")) return .empty(.method_not_allowed);
        return .{ .content_type = "text/plain", .body = "ok" };
    }

    if (std.mem.eql(u8, path, "/kv")) {
        if (!std.mem.eql(u8, method, "GET")) return .empty(.method_not_allowed);
        return .{
            .content_type = "application/json",
            .body = try jsonStringArray(arena, try store.keys(io, arena)),
        };
    }

    if (std.mem.startsWith(u8, path, kv_prefix)) {
        const key = path[kv_prefix.len..];
        if (!isValidKey(key)) return .empty(.bad_request);
        return handleKey(io, arena, store, method, key, req.body);
    }

    return .empty(.not_found);
}

fn handleKey(
    io: Io,
    arena: Allocator,
    store: *Store,
    method: []const u8,
    key: []const u8,
    body: []const u8,
) Allocator.Error!http.Response {
    if (std.mem.eql(u8, method, "GET")) {
        const value = try store.get(io, arena, key) orelse return .empty(.not_found);
        return .{ .content_type = "application/octet-stream", .body = value };
    }
    if (std.mem.eql(u8, method, "PUT")) {
        return switch (try store.put(io, key, body)) {
            .created => .empty(.created),
            .replaced => .empty(.ok),
        };
    }
    if (std.mem.eql(u8, method, "DELETE")) {
        return .empty(if (store.remove(io, key)) .no_content else .not_found);
    }
    return .empty(.method_not_allowed);
}

/// Keys are restricted to `[A-Za-z0-9_-]`, so no JSON escaping is ever required.
fn jsonStringArray(arena: Allocator, items: []const []const u8) Allocator.Error![]const u8 {
    var size: usize = 2;
    for (items) |item| size += item.len + 3;
    var out: std.ArrayList(u8) = try .initCapacity(arena, size);
    out.appendAssumeCapacity('[');
    for (items, 0..) |item, i| {
        if (i != 0) out.appendAssumeCapacity(',');
        out.appendAssumeCapacity('"');
        out.appendSliceAssumeCapacity(item);
        out.appendAssumeCapacity('"');
    }
    out.appendAssumeCapacity(']');
    return out.items;
}

test isValidKey {
    try std.testing.expect(isValidKey("a"));
    try std.testing.expect(isValidKey("A-z_09"));
    try std.testing.expect(isValidKey("k" ** 64));
    try std.testing.expect(!isValidKey(""));
    try std.testing.expect(!isValidKey("k" ** 65));
    try std.testing.expect(!isValidKey("a/b"));
    try std.testing.expect(!isValidKey("bad.key"));
    try std.testing.expect(!isValidKey("a%20"));
}

test "routes and status codes" {
    const io = std.testing.io;
    var arena_state: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    var store: Store = .init(std.testing.allocator);
    defer store.deinit();

    const Case = struct { method: []const u8, target: []const u8, body: []const u8 = "", status: http.Status };
    const cases = [_]Case{
        .{ .method = "GET", .target = "/health", .status = .ok },
        .{ .method = "POST", .target = "/health", .status = .method_not_allowed },
        .{ .method = "PUT", .target = "/kv/b", .body = "2", .status = .created },
        .{ .method = "PUT", .target = "/kv/a", .body = "1", .status = .created },
        .{ .method = "PUT", .target = "/kv/a", .body = "one", .status = .ok },
        .{ .method = "GET", .target = "/kv/a", .status = .ok },
        .{ .method = "PATCH", .target = "/kv/a", .status = .method_not_allowed },
        .{ .method = "GET", .target = "/kv/", .status = .bad_request },
        .{ .method = "GET", .target = "/kv/a/b", .status = .bad_request },
        .{ .method = "POST", .target = "/kv", .status = .method_not_allowed },
        .{ .method = "GET", .target = "/nope", .status = .not_found },
        .{ .method = "DELETE", .target = "/kv/b", .status = .no_content },
        .{ .method = "DELETE", .target = "/kv/b", .status = .not_found },
        .{ .method = "GET", .target = "/kv/b", .status = .not_found },
    };
    for (cases) |c| {
        const req: http.Request = .{ .method = c.method, .target = c.target, .headers = &.{}, .body = c.body };
        const res = try handle(io, arena, &store, &req);
        try std.testing.expectEqual(c.status, res.status);
    }

    const req: http.Request = .{ .method = "GET", .target = "/kv", .headers = &.{}, .body = "" };
    const res = try handle(io, arena, &store, &req);
    try std.testing.expectEqualStrings("[\"a\"]", res.body);
    try std.testing.expectEqualStrings("application/json", res.content_type.?);
}
